"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

Test-day runbook step 8 (written 2026-11-22, before any metric): are all runs complete? Reads only file lists,
.meta.json / missing.json counts, answer counts and times; it reads no score value and no label, so it computes no
metric. Checks:
  A  API score files: the four finals and every plan 7.5 candidate (answers mode, 19,227 questions, 0 missing), and
     each responses file has every question once (no duplicate answers);
  B  local systems on the split: the same files as the dev rehearsal of the final path (dev -> split in the names);
     B2-local's six score files hold every point and question;
  C  grounding package: groups, the L1 forward, the local systems and VoxTurn in every condition; the API runs of
     b3 (both settings), b2fast and b2strong with 0 missing per condition and 34 repeats where registered;
  D  noise analysis: every level has the dev rehearsal's files and the three rivals' answers files (0 missing);
  E  modes: modes.json says answers for every rival and no probability-mode folder exists on the split;
  F  drift rule (amendment 13.4): every answer on the split was asked after a complete, passed drift check of the
     same day for that rival, and that check was the day's first complete one in answers mode.
usage (repo root): .venv-gpu/Scripts/python.exe -X utf8 scripts/p1v4_step8_check.py [split]
Output: results/main_v04/step8_check_<split>.json
"""
import glob
import json
import os
import sys

R = "data/p1v4/runs"
NAME = {"b2fast": "B2-fast", "b2strong": "B2-strong", "b3": "B3", "b2ideal": "B2-ideal"}
FINALS = {"b2fast": "K48_think_prec", "b2strong": "K48_think_prec", "b3": "A6_nothink_prec", "b2ideal": "K48_nothink"}
CANDS = {"b2fast": [f"K{n}_{t}_prec" for n in (6, 24, 48) for t in ("nothink", "think")],
         "b2strong": [f"K{n}_{t}_prec" for n in (6, 24, 48) for t in ("nothink", "think")],
         "b3": [f"A{n}_{t}_prec" for n in (0, 6) for t in ("nothink", "think")]}
CONDS = ("none", "c0.3", "c0.5", "c0.7", "c0.9", "c0.99", "mv0.5", "mv0.9", "mv0.99")
ALL_CONDS = ("natural",) + CONDS
LEVELS = ("dclean", "dnoise5", "dnoise10")
LOCAL = ("l1", "l2", "l3", "t", "t0", "t0single", "b1", "b1_best", "refs", "readouts", "b2local")


def answers_of(path):
    ok, dup = {}, 0
    for line in open(path, encoding="utf-8"):
        r = json.loads(line)
        if r["status"] != 200:
            continue
        k = (r["id"], r["q"])
        dup += k in ok
        ok[k] = r["time"]
    return ok, dup


def main(split="test"):
    out, fails = {}, []

    # A: API score files
    a = {}
    for sd in ("b2fast", "b2strong", "b3", "b2ideal"):
        for s in sorted(set(CANDS.get(sd, []) + [FINALS[sd]])):
            base = f"{R}/final/{split}/api/{sd}/scores_{split}_{s}_answers"
            meta = json.load(open(base + ".meta.json")) if os.path.exists(base + ".meta.json") else None
            ok, dup = answers_of(f"{R}/final/{split}/api/{sd}/{s}_answers/responses.jsonl") \
                if os.path.exists(f"{R}/final/{split}/api/{sd}/{s}_answers/responses.jsonl") else ({}, 0)
            good = (os.path.exists(base + ".json") and meta is not None and meta["missing"] == 0
                    and meta["mode"] == "answers" and meta["questions"] == len(ok) and dup == 0)
            a[f"{sd} {s}"] = {"score_file": os.path.exists(base + ".json"), "questions": None if meta is None else
                              meta["questions"], "missing": None if meta is None else meta["missing"],
                              "answered_once": len(ok), "duplicates": dup, "ok": good}
            if not good:
                fails.append(f"A {sd} {s}")
    out["A_api_scores"] = a

    # B: local systems (same files as the dev rehearsal)
    b = {}
    for s in LOCAL:
        dev = {f.replace("_dev", f"_{split}") for f in os.listdir(f"{R}/final/dev/{s}")} if \
            os.path.isdir(f"{R}/final/dev/{s}") else set()
        got = set(os.listdir(f"{R}/final/{split}/{s}")) if os.path.isdir(f"{R}/final/{split}/{s}") else set()
        missing = sorted(dev - got)
        b[s] = {"files": len(got), "missing_vs_dev": missing}
        if missing or not got:
            fails.append(f"B {s}")
    for K in (6, 24, 48):
        for rd in ("first", "label"):
            p = f"{R}/final/{split}/b2local/scores_{split}_K{K}_{rd}.json"
            d = json.load(open(p)) if os.path.exists(p) else {}
            n_q = sum(len(v) for v in d.values())
            b[f"b2local K{K} {rd}"] = {"points": len(d), "questions": n_q}
    n_pts = {v["points"] for k, v in b.items() if k.startswith("b2local K")}
    n_qs = {v["questions"] for k, v in b.items() if k.startswith("b2local K")}
    if len(n_pts) != 1 or len(n_qs) != 1 or 0 in n_pts:
        fails.append("B b2local counts")
    out["B_local"] = b

    # C: grounding package
    g, gd = {}, f"{R}/grounding/{split}"
    need = ["groups.json", "voxturn_matched.json"] + [f"l1_{c}.npz" for c in ALL_CONDS] + \
        [f"local_{c}.json" for c in ALL_CONDS] + [f"feats_{c}" for c in ALL_CONDS]
    g["missing_files"] = [f for f in need if not os.path.exists(f"{gd}/{f}")]
    if g["missing_files"]:
        fails.append("C files")
    runs = {"b3 A6_nothink_prec_answers": 34, "b3 A6_nothink_answers": 0,
            "b2fast K48_think_prec_answers": 34, "b2strong K48_think_prec_answers": 34}
    for run, rep in runs.items():
        sd, leaf = run.split()
        for c in CONDS:
            d = f"{gd}/api/{sd}/{leaf}/{c}"
            m = json.load(open(f"{d}/missing.json")) if os.path.exists(f"{d}/missing.json") else None
            ok, dup = answers_of(f"{d}/responses.jsonl") if os.path.exists(f"{d}/responses.jsonl") else ({}, 0)
            r_ok, _ = answers_of(f"{d}/repeat.jsonl") if os.path.exists(f"{d}/repeat.jsonl") else ({}, 0)
            good = m is not None and m["missing"] == 0 and m["asked"] == len(ok) and dup == 0 and len(r_ok) == rep
            g[f"{run} {c}"] = {"asked": None if m is None else m["asked"], "missing": None if m is None else
                               m["missing"], "answered_once": len(ok), "duplicates": dup, "repeats": len(r_ok),
                               "ok": good}
            if not good:
                fails.append(f"C {run} {c}")
    out["C_grounding"] = g

    # D: noise analysis
    nz = {}
    dev_files = set(os.listdir(f"{R}/final/dev/noise/dclean"))
    for lv in LEVELS:
        d = f"{R}/final/{split}/noise/{lv}"
        got = set(os.listdir(d)) if os.path.isdir(d) else set()
        miss = sorted(dev_files - got)
        metas = {}
        for n in ("B2-fast", "B2-strong", "B3"):
            p = f"{d}/{n}_answers.meta.json"
            m = json.load(open(p)) if os.path.exists(p) else None
            metas[n] = None if m is None else {k: m.get(k) for k in ("questions", "missing", "mode", "setting")}
            if m is None or m["missing"] != 0 or m["mode"] != "answers":
                fails.append(f"D {lv} {n}")
        nz[lv] = {"missing_vs_dev": miss, "rivals": metas}
        if miss:
            fails.append(f"D {lv} files")
    out["D_noise"] = nz

    # E: modes
    modes = json.load(open(f"{R}/final/{split}/api/modes.json"))
    leaves = [p for p in glob.glob(f"{R}/final/{split}/api/*/*/") + glob.glob(f"{R}/grounding/{split}/api/*/*/") +
              glob.glob(f"{R}/final/{split}/noise/*/api/*/*/") if not p.rstrip("/\\").endswith("_answers")]
    out["E_modes"] = {"modes": modes, "probability_folders": [p.replace("\\", "/") for p in leaves]}
    if set(modes.values()) != {"answers"} or leaves:
        fails.append("E modes")

    # F: drift rule
    checks = [json.loads(x) for x in open(f"{R}/final/{split}/api/drift_checks.jsonl", encoding="utf-8")]
    gov = {}
    for c in checks:                                   # the first complete check of the day in answers mode governs
        if c.get("complete") and c.get("mode") == "answers":
            gov.setdefault((c["system"], c["time"][:10]), c)
    files = glob.glob(f"{R}/final/{split}/api/*/*/responses.jsonl") + \
        glob.glob(f"{R}/grounding/{split}/api/*/*/*/*.jsonl") + \
        glob.glob(f"{R}/final/{split}/noise/*/api/*/*/responses.jsonl")
    f_out, n_ans, viol = {}, 0, 0
    for p in files:
        q = p.replace("\\", "/")
        sd = q.split("/api/")[1].split("/")[0]
        days = {}
        for line in open(p, encoding="utf-8"):
            r = json.loads(line)
            if r["status"] != 200:
                continue
            n_ans += 1
            day, t = r["time"][:10], r["time"][:16]
            c = gov.get((NAME[sd], day))
            bad = c is None or not c.get("pass") or t < c["time"][:16]
            viol += bad
            days.setdefault(day, [0, 0])
            days[day][0] += 1
            days[day][1] += bad
        f_out[q] = {d: {"answers": v[0], "before_or_without_a_passed_check": v[1]} for d, v in sorted(days.items())}
    out["F_drift"] = {"governing_checks": {f"{k[0]} {k[1]}": {x: v.get(x) for x in ("time", "setting", "flips",
                                                                                      "limit", "pass")}
                                           for k, v in sorted(gov.items())},
                      "answers": n_ans, "violations": viol, "files": f_out}
    if viol:
        fails.append("F drift")

    out["fails"] = fails
    out["pass"] = not fails
    os.makedirs("results/main_v04", exist_ok=True)
    json.dump(out, open(f"results/main_v04/step8_check_{split}.json", "w"), indent=1)
    print(f"A api score files: {sum(v['ok'] for v in a.values())}/{len(a)} ok")
    print(f"B local systems: {sum(not v['missing_vs_dev'] for k, v in b.items() if k in LOCAL)}/{len(LOCAL)} "
          f"complete; b2local points {sorted(n_pts)}, questions {sorted(n_qs)}")
    print(f"C grounding: files missing {len(g['missing_files'])}; API conditions ok "
          f"{sum(1 for k, v in g.items() if isinstance(v, dict) and v.get('ok'))}/{len(runs) * len(CONDS)}")
    print(f"D noise: levels with all files {sum(not v['missing_vs_dev'] for v in nz.values())}/{len(LEVELS)}; "
          f"rival files ok {sum(1 for v in nz.values() for m in v['rivals'].values() if m and m['missing'] == 0)}/9")
    print(f"E modes: {sorted(set(modes.values()))}; probability-mode folders {len(leaves)}")
    print(f"F drift rule: {n_ans} answers on {split}, {viol} asked before or without a passed check of the day")
    print("STEP 8", "PASS" if not fails else f"FAIL: {fails}", f"-> results/main_v04/step8_check_{split}.json")


if __name__ == "__main__":
    main(sys.argv[1] if len(sys.argv) > 1 else "test")
